export function getCongTrinh(slug: string): CongTrinh | undefined {
  return CONG_TRINH.find((p) => p.slug === slug);
}

export function relatedCongTrinh(slug: string, n = 6): CongTrinh[] {
  const self = getCongTrinh(slug);
  if (!self) return CONG_TRINH.slice(0, n);
  const same = CONG_TRINH.filter((p) => p.category === self.category && p.slug !== slug);
  const rest = CONG_TRINH.filter((p) => p.category !== self.category);
  return [...same, ...rest].slice(0, n);
}
